class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []  # list of (name, unit_price, quantity)
        self._discounts = []
        self._vouchers = []

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self._vouchers.append(amount)

    def total(self) -> float:
        items_value = sum(price * qty for _, price, qty in self._items)

        # Determine best single saving: max discount percent or voucher.
        best_saving = 0.0
        for percent in self._discounts:
            saving = items_value * (percent / 100.0)
            if saving > best_saving:
                best_saving = saving
        for voucher in self._vouchers:
            if voucher > best_saving:
                best_saving = voucher

        payable = items_value - best_saving
        if payable < 0:
            payable = 0.0

        # Shipping: free if items_value (before discounts) meets threshold.
        shipping = 0.0 if items_value >= self.free_shipping_threshold else self.shipping_cost

        return round(payable + shipping, 2)
